{"content": "from pypdf import PdfReader

reader = PdfReader("workspace/sc100-blank.pdf")

def qualified_name(obj):
    parts = []
    cur = obj
    while cur is not None:
        t = cur.get("/T")
        if t is None:
            break
        parts.append(str(t))
        cur = cur.get("/Parent")
        if cur is not None:
            cur = cur.get_object()
    return ".".join(reversed(parts))

out = []
for i, page in enumerate(reader.pages, start=1):
    annots = page.get("/Annots")
    if not annots:
        continue
    arr = annots.get_object()
    out.append(f"========== PAGE {i} ==========")
    for annot in arr:
        obj = annot.get_object()
        t = obj.get("/T")
        ft = obj.get("/FT")
        if t is None and ft is None:
            continue
        tu = obj.get("/TU")
        try:
            rect = [round(float(x),0) for x in obj.get("/Rect")]
        except Exception:
            rect = "?"
        ap = obj.get("/AP")
        names = []
        if ap:
            apobj = ap.get_object()
            n = apobj.get("/N")
            if n is not None:
                names = list(n.keys()) if hasattr(n, "keys") else [str(n)]
        parent = obj.get("/Parent")
        pt = None
        if parent is not None:
            pt = parent.get_object().get("/T")
        tu_s = (str(tu)[:60]) if tu else ""
        out.append(f"{qualified_name(obj)!r}  FT={ft} rect={rect} AP={names} par={pt} TU={tu_s!r}")

with open("temp/sc100-fullmap.txt", "w") as f:
    f.write("\n".join(out))
print("wrote", len(out), "lines")
", "file_path": "temp/fullmap.py"}

